{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "bundler",
    "lib": ["ES2022", "DOM", "DOM.Iterable"],
    "types": ["vite/client", "trusted-types"],
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "noImplicitOverride": true,
    "noFallthroughCasesInSwitch": true,
    "useUnknownInCatchVariables": true,
    "isolatedModules": true,
    "resolveJsonModule": true,
    "skipLibCheck": true,
    "noEmit": true
  },
  "include": ["src/**/*.ts", "harness/entry.ts", "harness/trusted-boundary.ts"]
}
---TSEC---
{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "noEmit": true,
    "plugins": [
      {
        "name": "tsec",
        "exemptionConfig": "./tsec-exemptions.json"
      }
    ]
  }
}
---EX---
{
  "ban-trustedtypes-createpolicy": ["harness/trusted-boundary.ts"]
}
