// Porto Notes — a shared notes board. Loaded by harness/entry.ts, after the Trusted Types boundary.
import './style.css';
import { createNoteElement } from './feed';
import { type FragmentState, parseFragment, syncFragment } from './fragment';
import { plainText } from './richtext';
import { loadNotes, saveNotes } from './storage';
import type { Note } from './types';

function required<T extends Element>(selector: string): T {
  const element = document.querySelector<T>(selector);
  if (element === null) throw new Error(`Porto Notes: index.html is missing ${selector}`);
  return element;
}

const form = required<HTMLFormElement>('#note-form');
const titleInput = required<HTMLInputElement>('#title');
const bodyInput = required<HTMLTextAreaElement>('#body');
const avatarInput = required<HTMLInputElement>('#avatar');
const searchInput = required<HTMLInputElement>('#search');
const resultsLine = required<HTMLParagraphElement>('#results-line');
const feed = required<HTMLElement>('#feed');

let notes: Note[] = loadNotes();
let query = '';
let selectedId: number | null = null;

/* ── search ─────────────────────────────────────────────────────────────── */

function normalize(text: string): string {
  return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

// A note is searchable both as typed and as read: "Santiago vs Brasão" should match a body that
// puts a </b> between those words. The two forms are kept apart so a match cannot straddle them.
const searchIndex = new Map<string, string>();

function searchableText(note: Note): string {
  const key = `${note.id}�${note.title}�${note.body}`;
  let indexed = searchIndex.get(key);
  if (indexed === undefined) {
    indexed = [note.title, note.body, plainText(note.title), plainText(note.body)]
      .map(normalize)
      .join('�');
    searchIndex.set(key, indexed);
  }
  return indexed;
}

function newestFirst(list: Note[]): Note[] {
  return [...list].sort((a, b) => {
    const at = Date.parse(a.createdAt);
    const bt = Date.parse(b.createdAt);
    return (Number.isNaN(bt) ? 0 : bt) - (Number.isNaN(at) ? 0 : at) || b.id - a.id;
  });
}

function visibleNotes(): Note[] {
  const needle = normalize(query);
  const ordered = newestFirst(notes);
  return needle === '' ? ordered : ordered.filter((note) => searchableText(note).includes(needle));
}

/* ── rendering ──────────────────────────────────────────────────────────── */

function render(): void {
  const visible = visibleNotes();
  const children: Node[] = visible.map(createNoteElement);

  if (children.length === 0) {
    const empty = document.createElement('p');
    empty.className = 'feed-empty';
    empty.textContent =
      normalize(query) === '' ? 'No notes yet — add the first one above.' : 'No notes match this search.';
    children.push(empty);
  }
  feed.replaceChildren(...children);

  resultsLine.textContent = query === '' ? '' : `results for "${query}"`;
  applySelection();
}

function applySelection(): void {
  for (const article of feed.querySelectorAll<HTMLElement>('article.note')) {
    const id = Number(article.dataset['noteId']);
    if (selectedId !== null && id === selectedId) article.setAttribute('aria-current', 'true');
    else article.removeAttribute('aria-current');
  }
}

function currentState(): FragmentState {
  return { query, selectedId };
}

/* ── events ─────────────────────────────────────────────────────────────── */

function selectFrom(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  const article = target.closest('.note-title')?.closest<HTMLElement>('article.note');
  if (article === undefined || article === null) return false;

  const id = Number(article.dataset['noteId']);
  if (!Number.isFinite(id)) return false;

  selectedId = id;
  applySelection();
  syncFragment(currentState());
  return true;
}

feed.addEventListener('click', (event) => {
  selectFrom(event.target);
});

feed.addEventListener('keydown', (event) => {
  if (event.key !== 'Enter' && event.key !== ' ') return;
  if (selectFrom(event.target)) event.preventDefault();
});

searchInput.addEventListener('input', () => {
  query = searchInput.value;
  render();
  syncFragment(currentState());
});

form.addEventListener('submit', (event) => {
  event.preventDefault();

  const title = titleInput.value.trim();
  const body = bodyInput.value;
  if (title === '' && body.trim() === '') return;

  const nextId = notes.reduce((highest, note) => Math.max(highest, note.id), 0) + 1;
  notes = [
    { id: nextId, title, body, avatar: avatarInput.value.trim(), createdAt: new Date().toISOString() },
    ...notes,
  ];
  saveNotes(notes);

  form.reset();
  render();
  titleInput.focus();
});

/** A fragment typed, shared or navigated to restores the query and the selection. */
function applyFragment(): void {
  const state = parseFragment(location.hash);
  query = state.query;
  selectedId = state.selectedId;
  searchInput.value = query;
  render();
}

window.addEventListener('hashchange', () => {
  applyFragment();
});

applyFragment();
syncFragment(currentState());

