import { chromium } from '@playwright/test';
import { spawn } from 'node:child_process';

const APP = '/workspace/benchmark/runs/lanes/lane-0/arm-b-harness';
const srv = spawn('node', [`${APP}/harness/server.mjs`, '--port', '4188'], { stdio: ['ignore', 'inherit', 'inherit'] });
await new Promise((r) => setTimeout(r, 800));

const browser = await chromium.launch();
const page = await browser.newPage();
const problems = [];
page.on('console', (m) => { if (m.type() === 'error') problems.push('console: ' + m.text()); });
page.on('pageerror', (e) => problems.push('pageerror: ' + e.message));
const check = (ok, label, extra = '') => console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : '  <- ' + extra}`);

const BASE = 'http://127.0.0.1:4188/';
await page.goto(BASE);

// seed + newest first
const titles = await page.locator('.note-title').allInnerTexts();
check(titles.length === 6, 'seeds 6 fixture notes', titles.length);
check(titles[0] === 'Keynote room', 'newest first', titles[0]);

// rich text renders
check((await page.locator('.note[data-note-id="1"] .note-body b').innerText()) === 'OWASP AppSec Days Porto', 'bold renders');
check((await page.locator('.note[data-note-id="2"] .note-body i').innerText()) === 'Ribeira', 'italic renders');
check((await page.locator('.note[data-note-id="1"] .note-body br').count()) === 1, 'br renders');
const href = await page.locator('.note[data-note-id="4"] .note-body a').getAttribute('href');
check(href === 'https://www.livrarialello.pt/', 'link clickable with href', href);
check((await page.locator('.note[data-note-id="1"] img.note-avatar').count()) === 1, 'avatar img present');
check((await page.locator('.note[data-note-id="2"] img.note-avatar').count()) === 0, 'no avatar img when blank');

// search + results line + fragment
await page.fill('#search', 'douro');
check((await page.locator('article.note').count()) === 2, 'search filters', await page.locator('article.note').count());
check((await page.locator('#results-line').innerText()) === 'results for "douro"', 'results line', await page.locator('#results-line').innerText());
check(page.url().endsWith('#q=douro'), 'fragment has q', page.url());

// select -> combined fragment
await page.click('.note[data-note-id="5"] .note-title');
check(page.url().endsWith('#q=douro&note=5'), 'combined fragment order', page.url());
check((await page.getAttribute('.note[data-note-id="5"]', 'aria-current')) === 'true', 'aria-current set');
check((await page.locator('[aria-current="true"]').count()) === 1, 'exactly one aria-current');

// deep link restores on reload
await page.goto(BASE + '#q=port&note=3');
check((await page.inputValue('#search')) === 'port', 'query restored', await page.inputValue('#search'));
check((await page.getAttribute('.note[data-note-id="3"]', 'aria-current')) === 'true', 'selection restored');
check((await page.locator('#results-line').innerText()) === 'results for "port"', 'results line restored');

// clearing the query empties the results line and keeps the note in the fragment
await page.fill('#search', '');
check((await page.locator('#results-line').innerText()) === '', 'results line empty when no query');
check(page.url().endsWith('#note=3'), 'fragment drops q', page.url());

// add a note: rich text, avatar, id continues, persists over reload, form cleared
await page.goto(BASE);
await page.fill('#title', 'Ponte Luís I');
await page.fill('#body', 'Cross <b>on foot</b> at the top.\nThen a <a href="https://example.com/port">port</a> tasting.');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type="submit"]');
const first = page.locator('article.note').first();
check((await first.getAttribute('data-note-id')) === '7', 'new id continues sequence', await first.getAttribute('data-note-id'));
check((await first.locator('.note-body b').innerText()) === 'on foot', 'new note bold renders');
check((await first.locator('.note-body br').count()) === 1, 'newline became a line break');
check((await first.locator('img.note-avatar').count()) === 1, 'new note avatar');
check((await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '', 'form cleared');
await page.reload();
check((await page.locator('article.note').count()) === 7, 'persisted over reload', await page.locator('article.note').count());

// search matches across a formatting tag and on the raw markup alike
await page.fill('#search', 'Santiago vs Brasão');
check((await page.locator('article.note').count()) === 1, 'search matches across tags', await page.locator('article.note').count());

// hostile input stays inert
await page.goto(BASE);
let alerted = false;
page.on('dialog', async (d) => { alerted = true; await d.dismiss(); });
await page.fill('#title', '<img src=x onerror=alert(1)>pwn');
await page.fill('#body', '<script>alert(2)</script><a href="javascript:alert(3)">click</a><b onmouseover=alert(4)>hover</b>');
await page.fill('#avatar', 'javascript:alert(5)');
await page.click('#note-form button[type="submit"]');
const evil = page.locator('article.note').first();
await evil.locator('.note-body b').hover();
await evil.locator('.note-body a').click({ trial: true }).catch(() => {});
await page.waitForTimeout(400);
check(!alerted, 'no dialog fired');
check((await evil.locator('script, img[onerror], [onmouseover]').count()) === 0, 'no script/handler nodes');
check((await evil.locator('.note-body a').getAttribute('href')) === null, 'javascript: href dropped');
check((await evil.locator('img.note-avatar').count()) === 0, 'javascript: avatar dropped');
check((await evil.locator('.note-body b').innerText()) === 'hover', 'safe formatting still kept');

// keyboard selection
await page.goto(BASE);
await page.locator('.note[data-note-id="6"] .note-title').focus();
await page.keyboard.press('Enter');
check(page.url().endsWith('#note=6'), 'keyboard selects', page.url());

console.log(problems.length ? 'PAGE PROBLEMS:\n' + problems.join('\n') : 'no console errors / page errors');
await browser.close();
srv.kill();

